static void test_sha256_split_blocks()
{
  uint8_t msg[64]={
    0x00, 0x01, 0x02, 0x03,
    0x04, 0x05, 0x06, 0x07,
    0x08, 0x09, 0x0A, 0x0B,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
    0x3C, 0x3D, 0x3E, 0x3F,
  };
  uint32_t out[16]={0};
  uint32_t words_expected[16]={0};
  words_expected[0]=0x00010203;
  words_expected[1]=0x04050607;
  words_expected[2]=0x08090A0B;
  words_expected[15]=0x3C3D3E3F;
  sha256_split_blocks(msg,ARRAY_LEN(msg),out);
  TEST_ASSERT_EQUAL_UINT32_ARRAY(out,words_expected,16);
}

